#ifndef ZOVUTILS_TTY_SYNC_BACKEND_H
#define ZOVUTILS_TTY_SYNC_BACKEND_H
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
static inline int zov_tty_run(int argc,char**argv){int silent=0;for(int i=0;i<argc;i++){const char*a=argv[i];if(!strcmp(a,"--help")){puts("Usage: tty [OPTION]...\nPrint the file name of the terminal connected to standard input.\n  -s, --silent, --quiet  print nothing, only return an exit status\n      --help             display this help and exit\n      --version          output version information and exit");return 0;}if(!strcmp(a,"--version")){puts("tty (zovutils) 0.10.10");return 0;}if(!strcmp(a,"-s")||!strcmp(a,"--silent")||!strcmp(a,"--quiet")){silent=1;continue;}if(a[0]=='-'){if(a[1]=='-')fprintf(stderr,"tty: unrecognized option '%s'\nTry 'tty --help' for more information.\n",a);else fprintf(stderr,"tty: invalid option -- '%c'\nTry 'tty --help' for more information.\n",a[1]?a[1]:'-');return 2;}fprintf(stderr,"tty: extra operand '%s'\nTry 'tty --help' for more information.\n",a);return 2;}if(isatty(STDIN_FILENO)){if(!silent){char*p=ttyname(STDIN_FILENO);if(p)puts(p);else{puts("not a tty");return 1;}}return 0;}if(!silent)puts("not a tty");return 1;}
static inline int zov_sync_run(int argc,char**argv){int filesystem=0,nf=0,options=1;const char**files=(const char**)malloc((size_t)(argc+1)*sizeof(char*));if(!files)return 1;for(int i=0;i<argc;i++){const char*a=argv[i];if(options&&!strcmp(a,"--")){options=0;continue;}if(options&&(!strcmp(a,"--help")||!strcmp(a,"--version"))){if(!strcmp(a,"--version")){puts("sync (zovutils) 0.10.10");free(files);return 0;}puts("Usage: sync [OPTION]... [FILE]...\nSynchronize cached writes to persistent storage.\n  -d, --data             sync only file data, not metadata\n  -f, --file-system      sync the file systems that contain the files\n      --help             display this help and exit\n      --version          output version information and exit");free(files);return 0;}if(options&&(!strcmp(a,"-f")||!strcmp(a,"--file-system"))){filesystem=1;continue;}if(options&&!strcmp(a,"-d")){continue;}if(options&&a[0]=='-'&&strcmp(a,"-")){fprintf(stderr,"sync: unrecognized option '%s'\nTry 'sync --help' for more information.\n",a);free(files);return 1;}files[nf++]=a;}int status=0;if(!nf){sync();free(files);return 0;}for(int i=0;i<nf;i++){int fd=open(files[i],O_RDONLY);if(fd<0){fprintf(stderr,"sync: %s: %s\n",files[i],strerror(errno));status=1;continue;}int rc=fsync(fd);int e=errno;close(fd);if(rc<0){fprintf(stderr,"sync: %s: %s\n",files[i],strerror(e));status=1;}(void)filesystem;}free(files);return status;}
#endif
